fun testToStrings() {
    assertThat(toStrings("a", "b")).containsExactly("a", "b").inOrder()
    assertThat(toStrings("a", listOf("b", "c"), 123)).containsExactly("a", "b", "c", "123").inOrder()
    assertThat(
        toStrings(
          object : Any() {
            override fun toString() = "custom"
          }
        )
      )
      .containsExactly("custom")
  }

